INSERT INTO accounting_setup(mapping_key,account_id) SELECT seed.mapping_key,a.id FROM (SELECT 'cash_on_hand' mapping_key,'111001' account_code UNION ALL SELECT 'bank_account','111010' UNION ALL SELECT 'ar_control','112001' UNION ALL SELECT 'supplier_advance','113001' UNION ALL SELECT 'subcontractor_advance','113002' UNION ALL SELECT 'employee_custody','114001' UNION ALL SELECT 'employee_advance','114002' UNION ALL SELECT 'ap_control','211001' UNION ALL SELECT 'subcontract_payable','212001' UNION ALL SELECT 'client_advance','213001' UNION ALL SELECT 'cost_plus_revenue','410001' UNION ALL SELECT 'boq_revenue','410002' UNION ALL SELECT 'lump_sum_revenue','410003' UNION ALL SELECT 'variation_revenue','410010' UNION ALL SELECT 'material_cost','510001' UNION ALL SELECT 'subcontract_cost','520001' UNION ALL SELECT 'direct_labor_cost','530001' UNION ALL SELECT 'equipment_cost','540001' UNION ALL SELECT 'site_expense','550001' UNION ALL SELECT 'other_project_cost','590001') seed JOIN accounts a ON a.account_code=seed.account_code ON DUPLICATE KEY UPDATE account_id=VALUES(account_id);
